    explanation_bn: "'SURGEON' শব্দে মোট ৭টি বর্ণ রয়েছে। ব্যঞ্জনবর্ণ ৪টি: S, R, G, N এবং স্বরবর্ণ ৩টি: U, E, O। স্বরবর্ণ তিনটিকে একটি একক বর্ণ (U,E,O) বিবেচনা করলে মোট বর্ণ দাঁড়ায় ৪ + ১ = ৫টি। এই ৫টি বর্ণ নিজেদের মধ্যে বিন্যস্ত হতে পারে ৫! = ১২০ উপায়ে। আবার ৩টি স্বরবর্ণ নিজেদের মধ্যে সাজানো যায় ৩! = ৬ উপায়ে। অতএব মোট বিন্যাস সংখ্যা = ১২০ × ৬ = ৭২০ উপায়ে।",
