    explanation_bn: "মোট পরীক্ষার্থী n(U) = ৫০। উভয় বিষয়ে ফেল = ১০ জন; অতএব অন্তত এক বিষয়ে পাস করেছে = ৫০ - ১০ = ৪০ জন। আমরা জানি: n(A ∪ B) = n(A) + n(B) - n(A ∩ B)। মান বসালে পাই: ৪০ = ৩৫ + ২৫ - n(A ∩ B) => ৪০ = ৬০ - n(A ∩ B) => n(A ∩ B) = ৬০ - ৪০ = ২০ জন। সুতরাং উভয় বিষয়ে পাস করেছে ২০ জন।",
